def camel_to_snake(s):
    """Convert CamelCase to snake_case."""
    if not s:
        return s

    result = []
    for i, c in enumerate(s):
        if c.isupper():
            # Check if we need to insert an underscore before this capital
            # Case 1: Previous char is lowercase -> insert underscore
            # Case 2: This is not the first char, previous is uppercase, and next is lowercase
            #         (this handles 'HTMLDate' -> 'html_date')
            if i > 0:
                prev = s[i - 1]
                if prev.islower():
                    result.append('_')
                elif prev.isupper() and i + 1 < len(s) and s[i + 1].islower():
                    # We're at the last capital of an acronym sequence before a lowercase
                    result.append('_')
        result.append(c.lower())

    return ''.join(result)
